local LuaParametersExpand = CS.Engine.Modules.LuaParametersExpand

local GlobalsInDreamSpace = CS.DreamSpace.GlobalsInDreamSpace


-- ========================================================

local currentInstance = nil

-- ========================================================

function RoomActivatorManager:__init()

    self.roleDelayFollow = nil -- DelayFollow; "vTarget-DelayFollow"
    self._isIgnoreRoomHide = true
    self.rooms = {} -- k:roomInstanceId; v:Room
end


function RoomActivatorManager:__delete()
    self.rooms = {}
end


function RoomActivatorManager:Awake()
    if currentInstance == nil then 
        currentInstance = self
    else 
        assert( false, "不允许存在 第二个 RoomActivatorManager 实例" )
    end 
end



function RoomActivatorManager:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end

    ---
    local selfParams = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( selfParams )
    self._isIgnoreRoomHide = LuaParametersReader.Read( selfParams, "isIgnoreRoomHide", LuaParametersType.Bool ) -- 若禁用, 所有 room 将全程激活状态

end 


function RoomActivatorManager:OnDestroy()
    currentInstance = nil
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



function RoomActivatorManager:Update()
    for k,room in pairs(self.rooms) do 
        room:SelfUpdate();
    end 
end



-- =============================================================== Self -> ================================================================== -- 


function RoomActivatorManager:GetIsIgnoreRoomHide()
    return self._isIgnoreRoomHide
end



