---@param room_   Room
function RoomActivatorManager:AddRoom( room_ )
    local roomInstanceId = room_.transform:GetInstanceID() -- Int32
    if self.rooms[roomInstanceId] == nil then 
        self.rooms[roomInstanceId] = room_
    end 
end




function RoomActivatorManager.WaitInstance()
    -- 只等待有限帧
    for i=1,DreamSpaceStates.DelayInitWaitFrames do 
        if isNotNull(currentInstance) then 
            break
        end 
        coroutine.yield(Yielders.EndOfFrame)
    end 
    assert( isNotNull(currentInstance), "始终没能等到 RoomActivatorManager 实例化, 请检查场景" )
end


function RoomActivatorManager.GetInstance()
    return currentInstance
end




function RoomActivatorManager:FindRole()

    if isNull( self.roleDelayFollow ) then 

        for i=0, DreamSpaceStates.DelayInitWaitFrames do 

            local roleDelayFollowCom = GlobalsInDreamSpace.FindComponent("vTargetDelayFollowBH")
            if isNotNull(roleDelayFollowCom) then 
                self.roleDelayFollow = DreamSpaceLuaUtils.GetLuaScr(roleDelayFollowCom.gameObject, "Game.DreamSpace.CharacterController.DelayFollow" )
                if isNotNull(self.roleDelayFollow) then
                    break
                end
            end 
            coroutine.yield(Yielders.EndOfFrame)
        end

        if isNull( self.roleDelayFollow ) then
            assert( false, "始终没能找到 gamoebj: SwitchablePlayer/VTarget/DelayFollow, 请查找原因" )
            return
        end
    end
end


function RoomActivatorManager:SetRoom( roomInstanceId, isActive_ )

    if self:GetIsIgnoreRoomHide() == true then 
        -- 只管开启, 不能隐藏
        isActive_ = true
    end 

    local room = self.rooms[roomInstanceId] -- Room
    assert( isNotNull( room ) )   
    room:SetRoom( isActive_ )
end



function RoomActivatorManager:GetRoom( roomInstanceId )
    local room = self.rooms[roomInstanceId] -- Room
    assert( isNotNull( room ) )
    return room
end




